package com.greenocean.backend;

import com.greenocean.backend.listener.planning.*;
import com.greenocean.backend.listener.live.*;
import com.greenocean.backend.auth.repository.UserRepository;
import com.greenocean.backend.auth.service.TokenService;
import com.greenocean.backend.account.repository.AccountRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;
import java.time.*;import java.util.*;
import static org.assertj.core.api.Assertions.*;

@SpringBootTest(properties={"greenocean.live-support.enabled=true","greenocean.listener-support.duration-enabled=true","greenocean.listener-support.scheduling-enabled=true","greenocean.listener-support.booking-enabled=true"})
@ActiveProfiles("test") @Transactional
class PhaseN1SchedulingTest {
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;
 @Autowired ListenerCalendar calendar;@Autowired ListenerBookings bookings;@Autowired ListenerSupportPolicy policy;@Autowired LiveSupportService live;@Autowired AccountRepository accounts;
 PhaseIFixtures.Actor member,listener,staff;Instant start;
 @BeforeEach void setup(){PhaseIFixtures.region(db);member=PhaseIFixtures.member(db,users,tokens);listener=PhaseIFixtures.member(db,users,tokens);staff=PhaseIFixtures.member(db,users,tokens);PhaseIFixtures.review(db,listener.id(),staff.id(),true);start=policy.now().plus(Duration.ofHours(3)).truncatedTo(java.time.temporal.ChronoUnit.MINUTES);window(listener.id(),start,start.plusSeconds(10800));}
 UUID window(UUID who,Instant a,Instant b){return calendar.exception(who,new ListenerCalendar.ExceptionInput("UTC",a.atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),b.atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),null,null,true));}
 ListenerBookings.Reservation input(Instant at){return new ListenerBookings.Reservation(listener.id(),at,UUID.randomUUID(),false);}
 Map<String,Object> reserve(){return bookings.reserve(member.id(),input(start));}
 void clock(Instant time){db.execute("CREATE OR REPLACE FUNCTION listener_support_now() RETURNS TIMESTAMPTZ LANGUAGE SQL VOLATILE AS $$ SELECT '"+time+"'::timestamptz $$");}
 @Test @Tag("happy") void genuineSlotsAreBoundedAndReadsCreateNothing(){var slots=calendar.slots(member.id(),listener.id(),2,null);assertThat(slots.items()).hasSize(2);assertThat(slots.hasNext()).isTrue();assertThat(slots.items().getFirst().endsAt()).isEqualTo(start.plusSeconds(1800));assertThat(calendar.slots(member.id(),listener.id(),2,slots.nextCursor()).items().getFirst().startsAt()).isAfter(slots.items().getLast().startsAt());assertThat(db.queryForObject("SELECT count(*) FROM listener_bookings WHERE member_id=?",Integer.class,member.id())).isZero();assertThat(db.queryForObject("SELECT count(*) FROM live_support_requests WHERE member_id=?",Integer.class,member.id())).isZero();}
 @Test @Tag("happy") void reservationRetryCancellationAndProtectedCalendar(){var in=input(start);var first=bookings.reserve(member.id(),in);UUID id=(UUID)first.get("id");assertThat(bookings.reserve(member.id(),in).get("id")).isEqualTo(id);UUID exception=db.queryForObject("SELECT exception_id FROM listener_bookings WHERE id=?",UUID.class,id);assertThatThrownBy(()->calendar.remove(listener.id(),exception,true,1)).isInstanceOf(LiveSupportException.class).hasMessageContaining("reservations");assertThat(bookings.cancel(id,listener.id()).get("status")).isEqualTo("CANCELLED_BY_LISTENER");assertThat(bookings.cancel(id,member.id()).get("status")).isEqualTo("CANCELLED_BY_LISTENER");assertThat(bookings.reserve(member.id(),in).get("status")).isEqualTo("CANCELLED_BY_LISTENER");}
 @Test @Tag("malicious") void ownershipAndInventedSlotsAreRejected(){var b=reserve();var stranger=PhaseIFixtures.member(db,users,tokens);assertThatThrownBy(()->bookings.view((UUID)b.get("id"),stranger.id())).isInstanceOf(LiveSupportException.class);assertThatThrownBy(()->bookings.cancel((UUID)b.get("id"),stranger.id())).isInstanceOf(LiveSupportException.class);assertThatThrownBy(()->bookings.reserve(member.id(),input(start.plusSeconds(17)))).isInstanceOf(LiveSupportException.class);}
 @Test @Tag("confused") void upcomingLimitAndMinimumLeadAreServerOwned(){reserve();bookings.reserve(member.id(),input(start.plusSeconds(policy.limits().slotStepSeconds())));assertThatThrownBy(()->bookings.reserve(member.id(),input(start.plusSeconds(2L*policy.limits().slotStepSeconds())))).hasMessageContaining("upcoming");}
 @Test @Tag("malicious") void blockedAndRevokedListenersCannotAcceptReservations(){db.update("INSERT INTO blocks(blocker_id,blocked_id) VALUES(?,?)",member.id(),listener.id());assertThat(calendar.slots(member.id(),listener.id(),20,null).items()).isEmpty();assertThatThrownBy(this::reserve).isInstanceOf(LiveSupportException.class);}
 @Test @Tag("happy") void checkinAndScheduledHandoffPreserveThreeExplicitSteps(){UUID id=(UUID)reserve().get("id");assertThatThrownBy(()->bookings.checkin(id,member.id())).hasMessageContaining("opens");clock(start.minusSeconds(300));assertThat(bookings.checkin(id,member.id()).get("status")).isEqualTo("CHECKED_IN");assertThatThrownBy(()->bookings.handoff(id,member.id())).hasMessageContaining("appointment start");clock(start);assertThatThrownBy(()->bookings.handoff(id,member.id())).hasMessageContaining("not currently ready");live.setAvailability(listener.id(),listener.session(),0,true,null);var handoff=bookings.handoff(id,member.id());var request=(LiveSupportView)handoff.get("request");assertThat(request.conversationId()).isNull();live.accept(request.id(),listener.id());assertThat(live.get(request.id(),member.id()).conversationId()).isNull();var active=live.activate(request.id(),member.id());assertThat(active.conversationId()).isNotNull();assertThat(active.plannedEndsAt()).isEqualTo(start.plusSeconds(1800));assertThat(((LiveSupportView)bookings.handoff(id,member.id()).get("request")).id()).isEqualTo(request.id());}
 @Test @Tag("creative") void noShowAndQualificationLossHaveDifferentReasons(){UUID id=(UUID)reserve().get("id");clock(start.plusSeconds(600));bookings.reconcile();assertThat(bookings.view(id,member.id()).get("status")).isEqualTo("MEMBER_NO_SHOW");}
 @Test @Tag("malicious") void realReadinessCannotBypassNearTermReservation(){UUID id=(UUID)reserve().get("id");clock(start.minusSeconds(60));live.setAvailability(listener.id(),listener.session(),0,true,null);assertThatThrownBy(()->live.create(member.id(),UUID.randomUUID(),listener.id())).hasMessageContaining("No live listener");assertThat(bookings.view(id,member.id()).get("status")).isEqualTo("CONFIRMED");}
 @Test @Tag("creative") void dstGapAndRepeatedHoursRequireValidOffsets(){assertThatThrownBy(()->calendar.resolve("2027-03-14T02:30:00","America/Los_Angeles",null)).hasMessageContaining("does not exist");assertThatThrownBy(()->calendar.resolve("2026-11-01T01:30:00","America/Los_Angeles",null)).hasMessageContaining("explicit offset");assertThat(Duration.between(calendar.resolve("2026-11-01T01:30:00","America/Los_Angeles","-07:00"),calendar.resolve("2026-11-01T01:30:00","America/Los_Angeles","-08:00"))).isEqualTo(Duration.ofHours(1));assertThatThrownBy(()->calendar.resolve("2026-11-01T01:30:00","America/Los_Angeles","+03:00")).hasMessageContaining("Offset");}
 @Test @Tag("happy") void erasureRemovesPlanningRecords(){reserve();accounts.erase(member.id());assertThat(db.queryForObject("SELECT count(*) FROM listener_bookings WHERE member_id=?",Integer.class,member.id())).isZero();assertThat(db.queryForObject("SELECT count(*) FROM listener_calendar_exceptions WHERE listener_id=?",Integer.class,listener.id())).isPositive();}
}
